cat <<'EOF' > verify_fix.py
import astropy.units as u
import pytest

def test_return_none_annotation():
    class PoC(object):
        @u.quantity_input
        def __init__(self, voltage: u.V) -> None:
            pass

    # This should not raise AttributeError
    poc = PoC(1.*u.V)

def test_no_return_annotation():
    @u.quantity_input
    def func(voltage: u.V):
        pass

    # This should not raise
    func(1.*u.V)

def test_return_annotation_quantity():
    @u.quantity_input
    def func(val: u.m) -> u.cm:
        return val

    res = func(1.*u.m)
    assert res.unit == u.cm
    assert res.value == 100

def test_return_annotation_quantity_returning_none():
    @u.quantity_input
    def func(val: u.m) -> u.cm:
        return None

    # This should raise AttributeError because None has no .to()
    # This confirms we didn't change behavior for non-None annotations
    with pytest.raises(AttributeError):
        func(1.*u.m)

if __name__ == "__main__":
    try:
        test_return_none_annotation()
        print("test_return_none_annotation passed")
        test_no_return_annotation()
        print("test_no_return_annotation passed")
        test_return_annotation_quantity()
        print("test_return_annotation_quantity passed")
        test_return_annotation_quantity_returning_none()
        print("test_return_annotation_quantity_returning_none passed")
        print("All tests passed!")
    except Exception as e:
        print(f"Tests failed with {e}")
        import traceback
        traceback.print_exc()
        exit(1)
EOF
